        "context": "Khi nghiên cứu ảnh hưởng của công nghệ biofloc với nguồn carbon từ rỉ đường và bột ngô đến tăng trưởng của cá chép giống, 3 nghiệm thức (NT) thí nghiệm được bố trí gồm: NT1: ương bằng công nghệ biofloc với nguồn carbon từ rỉ đường; NT2: ương bằng công nghệ biofloc với nguồn carbon từ bột ngô; NT3: ương nuôi thông thường (đối chứng). Sau 60 ngày thí nghiệm, kết quả thu được như hình dưới đây (trục hoành gồm NT1, NT2, NT3; mỗi nghiệm thức có cột tỉ lệ sống (%) gồm NT1 = 98,33, NT2 = 95,83, NT3 = 90,83 và cột khối lượng kết thúc (g/con) gồm NT1 = 74,64, NT2 = 72,83, NT3 = 67,20).\\n(Nguồn: Đỗ Đăng Khoa và cộng sự (2022). Tạp chí Khoa học Nông nghiệp Việt Nam, 20(8), trang 1021-1030).\\nGhi chú: Khối lượng cá ban đầu đều bằng nhau ở các nghiệm thức.",
