        "number": 34,
        "context": "Задания 34 – 38. Прочитайте текст и выберите правильный вариант ответа.\nУрал — один из красивейших и богатейших районов России. Природа Урала богата и разнообразна. Уральские горы — самые древние горы на Земле. На Урале добывают нефть, газ, уголь, железо, медь, золото, серебро и платину. Благодаря большому количеству полезных ископаемых Урал стал одним из крупнейших промышленных районов России.\nУрал известен не только своими полезными ископаемыми, но и своими драгоценными и полудрагоценными камнями, которые называются самоцветами. Здесь, на Урале, лучшие уральские мастера создавали ювелирные изделия для царского двора. В городе Екатеринбурге в музее, который называется «Золотая кладовая», собрана богатейшая коллекция изделий из золота и драгоценных камней. Здесь можно увидеть ювелирные украшения, предметы искусства — вазы, шкатулки, картины, — сделанные уральскими мастерами.\nЛюди сочинили много сказок, песен и легенд о красоте и богатстве уральской природы, об уральских самоцветах и о талантливых мастерах, которые делали из камня прекрасные вещи. Вот почему путешественники, учёные, исследователи и предприниматели всегда интересовались Уралом и хотели здесь побывать.\nСегодня Урал стал не только важнейшим промышленным центром страны, но и местом для отдыха и путешествий. Особое впечатление на путешественников и туристов производят богатые леса Урала, красивые горные озёра с голубой водой, быстрые горные реки, а также замечательные изделия уральских мастеров из драгоценных и полудрагоценных камней.\n(Антонова В.Е., Нахабин М.М., Толстых А.А. Дорога в Россию: учебник русского языка (первый уровень): в 2 т. — Т. II. — 3-е изд. — СПб.: Златоуст, 2009)",
