        "prompt": "Lisez le texte et répondez aux questions en choisissant la bonne réponse.\n\nL'écart de salaires entre les hommes et les femmes s'est réduit de 0,4 point en 2024\nLa différence de revenu salarial entre les femmes et les hommes dans le secteur privé s'est élevée à 21,8 %, en 2024, a rapporté l'Institut national de la statistique et des études économiques (Insee), qui note que cet écart s'est réduit moins vite que les années précédentes.\nÀ ce rythme, il faudrait 54,5 années avant que l'écart moyen de salaires observé entre les hommes et les femmes ne se résorbe* entièrement. Dans le secteur privé, cette différence s'est élevée à 21,8 % en 2024, soit une baisse de 0,4 point, a annoncé jeudi 26 février l'Insee. Entre 2019 et 2023, cet écart s'était réduit à hauteur de 0,9 point par an en moyenne, relève l'institut, qui rappelle que les femmes sont plus nombreuses dans les métiers les moins rémunérateurs et exercent davantage de temps partiel.\nDes femmes en moyenne plus diplômées que les hommes\nÀ temps de travail identique, l'écart au détriment des femmes n'est plus « que » de 14 %. Il était de 22,1 % en 1995. Le volume de travail annuel des femmes restait inférieur de 9,1 % à celui des hommes en 2024, contre 14,9 % en 1995. L'Insee constate que les inégalités de salaires entre les deux sexes augmentent avec l'âge : l'écart à temps de travail identique n'est que de 3,2 % chez les moins de 25 ans contre 24,1 % chez les 60 ans et plus. En nombre d'heures, à l'inverse, les femmes de moins de 25 ans travaillent 15,8 % de moins que les hommes, un écart qui n'est plus de 7,9 % chez les 60 ans et plus. « Cela s'explique notamment par une insertion un peu plus tardive sur le marché du travail des femmes, car elles sont en moyenne plus diplômées que les hommes », selon l'étude.\n\n*Se résorber (v) : giảm dần, biến mất\n\nLes femmes entrent souvent un peu plus tard sur le marché du travail parce que (qu') ______.",
        "options": [
          "la carrière est moins importante pour elles",
          "elles pensent à avoir des enfants",
          "elles changent tardivement de travail",
          "elles consacrent du temps aux études"
        ]
